package com.travelbird.ai.service;
import com.travelbird.global.error.*;import java.util.*;
public final class AiRecommendationPolicy {private AiRecommendationPolicy(){} public static void general(List<Long> ids){if(ids!=null&&!ids.isEmpty())throw new BusinessException(ErrorCode.CONFLICTING_PLACE_POLICY);} public static void saved(List<Long> ids,Set<Long> owned,Set<Long> regional){if(ids==null||ids.isEmpty())throw new BusinessException(ErrorCode.INSUFFICIENT_SAVED_PLACES);var distinct=new HashSet<>(ids);if(!owned.containsAll(distinct))throw new BusinessException(ErrorCode.SAVED_PLACE_ACCESS_DENIED);if(!regional.containsAll(distinct))throw new BusinessException(ErrorCode.INCOMPATIBLE_PLACE_REGIONS);} public static void trip(List<Long> existing,List<Long> wishlist,int days){if(wishlist==null||wishlist.isEmpty())throw new BusinessException(ErrorCode.EMPTY_WISHLIST);var required=new HashSet<Long>();required.addAll(existing);required.addAll(wishlist);if(required.size()>days*15)throw new BusinessException(ErrorCode.AI_ROUTE_REQUIRED_PLACE_LIMIT_EXCEEDED);}}
